package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import java.math.*;import java.time.*;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;
/** Original-owner stop intent. A post-dispatch request is not provider termination or a billing receipt. */
public final class FormalInvocationCancellation {
 private final JdbcTemplate db;private final FormalVerificationJobs jobs;private final FormalInvocationReservations reservations;private final ResourceReadAuthority resources;private final FormalInvocationSchema schema;
 public FormalInvocationCancellation(DataSource data,FormalVerificationJobs jobs,FormalInvocationReservations reservations,ResourceReadAuthority resources,FormalInvocationSchema schema){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.jobs=jobs;this.reservations=reservations;this.resources=resources;this.schema=schema;}
 JsonNode cancel(EnterpriseAccess.Admission a,String invocation,String key,String reason)throws Exception{
  WireValues.uuid(invocation);if(key==null||!key.matches("[!-~]{16,128}")||reason==null||reason.isBlank()||reason.length()>2000||!reason.equals(reason.strip()))throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);
  String tenant=a.context().tenant_id(),actor=a.actorId();var run=one(db.query("SELECT run_id,created_by,config_id FROM invocation WHERE tenant_id=? AND invocation_id=? LIMIT 2",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3)),tenant,invocation));if(!actor.equals(run.get(1)))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);var job=jobs.byRun(tenant,run.get(0));reservations.requireRegistered(job,invocation);resources.require(a,new PermissionProtocol.Scope(tenant,job.project(),"CONFIGURATION",run.get(2)),"model.verify","MODEL_VERIFICATION");
  return cancelBound(a,new FormalInvocationBinding.Verification(job),invocation,key,reason);
 }
 JsonNode cancelTask(EnterpriseAccess.Admission a,TaskInvocationRecords.Binding task,String invocation,String key,String reason)throws Exception {
  WireValues.uuid(invocation);validate(key,reason);if(!a.formalWorker())throw new TenantAccessException(ErrorCode.ACCESS_DENIED);a.formalProof().requireActive();var i=a.formalProof().identity();var n=task.node();
  if(!"TASK".equals(i.executionKind())||!i.tenant().equals(task.tenant())||!i.project().equals(task.project())||!i.actor().equals(task.actor())||!i.run().equals(task.run())||!i.step().equals(task.step())||!i.action().equals(task.action())||!i.principal().equals(task.principal())||!i.generation().equals(n.lease_generation())||!i.workerService().equals(n.worker_service_uri()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
  reservations.requireRegistered(task,invocation);var model=task.original().dependencies().required("model");resources.require(a,new PermissionProtocol.Scope(task.tenant(),model.required("project_id").isNull()?null:model.required("project_id").textValue(),"CONFIGURATION",model.required("config_id").textValue()),"model.send",task.original().request().business_purpose());
  return cancelBound(a,task,invocation,key,reason);
 }
 /** Lifecycle authority can close original reservations after the run fence; it cannot authorize a model send. */
 JsonNode cancelLifecycle(TaskRunLifecycleAuthority.Proof proof,FormalInvocationBinding original,String invocation)throws Exception {
  proof.require(TaskRunLifecycleAuthority.Operation.REQUEST_CANCEL);var ref=proof.reference();
  if(!"CANCEL_REQUESTED".equals(proof.status())||!ref.tenantId().equals(original.tenant())||!ref.projectId().equals(original.project())||!ref.runId().equals(original.run())||!proof.admission().actorId().equals(original.actor())||!original.task())throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
  reservations.requireRegistered(original,invocation);
  return cancelBound(proof.admission(),original,invocation,"run-stop:"+invocation,"RUN_CANCELLATION");
 }
 /** Independent EVAL stop authority; never a TASK proof or model-send grant. */
 JsonNode cancelEvaluation(FormalEvaluationNodeRuntime.Cancellation proof,FormalEvaluationInvocationRecords.Binding original,String invocation)throws Exception {
  proof.requireCurrent();if(!proof.tenantId().equals(original.tenant())||!proof.projectId().equals(original.project())||!proof.runId().equals(original.run())||!proof.actorId().equals(original.actor()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
  var request=schema.parse(original.request());if(!"SYSTEM_JOB".equals(request.required("execution_kind").asText())||!"EVALUATION_VERIFICATION".equals(request.required("job_type").asText()))bad();reservations.requireRegistered(original,invocation);
  return cancelBound(proof.admission(),original,invocation,"evaluation-stop:"+invocation,"EVALUATION_CANCELLATION");
 }
 /** A genuine no-send disposition has no usage receipt and is deliberately not SETTLED. */
 static Optional<JsonNode> noSend(JdbcTemplate db,String tenant,String actor,String invocation)throws Exception {
  var rows=db.queryForList("SELECT c.* FROM formal_invocation_cancellation c JOIN invocation i ON i.tenant_id=c.tenant_id AND i.invocation_id=c.invocation_id AND i.created_by=c.created_by AND i.project_id=c.project_id WHERE c.tenant_id=? AND c.invocation_id=? AND c.created_by=? AND i.status='CANCELLED' AND i.dispatch_generation=0 AND i.actual_send_manifest IS NULL AND i.actual_send_sha256 IS NULL AND i.provider_request_id IS NULL AND i.usage_receipt_id IS NULL AND i.settled_amount IS NULL AND i.settlement_status='PENDING' LIMIT 2 FOR UPDATE",tenant,invocation,actor);
  if(rows.isEmpty())return Optional.empty();var row=one(rows);var mapper=new com.fasterxml.jackson.databind.ObjectMapper();String raw=(String)row.get("receipt_json");var receipt=mapper.readTree(raw);String request=(String)row.get("canonical_request");var req=mapper.readTree(request);
  if(!raw.equals(new String(ContentReadAuthorization.canonicalBytes(receipt),java.nio.charset.StandardCharsets.UTF_8))||!WireValues.sha256(ContentReadAuthorization.canonicalBytes(receipt)).equals(row.get("receipt_sha256"))||!WireValues.sha256(request.getBytes(java.nio.charset.StandardCharsets.UTF_8)).equals(row.get("request_sha256"))||!row.get("request_sha256").equals(receipt.path("request_body_sha256").asText())||!keyHash((String)row.get("idempotency_key")).equals(receipt.path("original_key_sha256").asText())||!invocation.equals(req.path("invocation_id").asText())||!invocation.equals(receipt.path("invocation_id").asText())||!"CANCELLED".equals(receipt.path("status").asText())||!receipt.path("before_dispatch").isBoolean()||!receipt.path("before_dispatch").booleanValue()||!receipt.path("reservations_released").isBoolean()||!receipt.path("reservations_released").booleanValue()||!receipt.path("provider_termination_confirmed").isBoolean()||receipt.path("provider_termination_confirmed").booleanValue())bad();
  if(!db.queryForList("SELECT attempt_id FROM formal_invocation_attempt WHERE tenant_id=? AND invocation_id=? LIMIT 1 FOR UPDATE",tenant,invocation).isEmpty())bad();
  var released=db.queryForList("SELECT status FROM budget_reservation WHERE tenant_id=? AND invocation_id=? LIMIT 3 FOR UPDATE",tenant,invocation);if(released.size()!=2||released.stream().anyMatch(r->!"RELEASED".equals(r.get("status"))))bad();
  var audit=one(db.queryForList("SELECT resource_ref,schema_version,schema_manifest_sha256,project_id,created_by,classification FROM audit_event WHERE tenant_id=? AND subject_id=? AND action='model.invocation_cancel_requested' AND result='SUCCESS' AND request_id=? AND trace_id=? AND created_at=? LIMIT 2 FOR UPDATE",tenant,actor,row.get("request_sha256"),invocation,row.get("created_at")));
  for(String key:List.of("schema_version","schema_manifest_sha256","project_id","created_by","classification"))if(!Objects.equals(row.get(key),audit.get(key)))bad();if(!raw.equals(new String(ContentReadAuthorization.canonicalBytes(mapper.readTree((String)audit.get("resource_ref"))),java.nio.charset.StandardCharsets.UTF_8)))bad();
  var event=one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND aggregate_id=? AND event_type='model.invocation_cancel_requested' AND occurred_at=? LIMIT 2 FOR UPDATE",tenant,invocation,row.get("created_at")));if(!raw.equals(new String(ContentReadAuthorization.canonicalBytes(mapper.readTree((String)event.get("payload"))),java.nio.charset.StandardCharsets.UTF_8)))bad();return Optional.of(receipt);
 }
 static void requireQuiescentTask(JdbcTemplate db,String tenant,String project,String task,ErrorCode pending)throws Exception {
  var rows=db.queryForList("SELECT i.invocation_id,i.created_by FROM invocation i JOIN task_run r ON r.tenant_id=i.tenant_id AND r.run_id=i.run_id WHERE r.tenant_id=? AND r.project_id=? AND r.task_id=? AND (i.status NOT IN ('SUCCEEDED','FAILED','CANCELLED') OR i.settlement_status<>'SETTLED') LIMIT 10001 FOR UPDATE",tenant,project,task);
  if(rows.size()>10000)throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);for(var row:rows)if(noSend(db,tenant,(String)row.get("created_by"),(String)row.get("invocation_id")).isEmpty())throw new TenantAccessException(pending);
 }
 private JsonNode cancelBound(EnterpriseAccess.Admission a,FormalInvocationBinding job,String invocation,String key,String reason)throws Exception {
  String tenant=a.context().tenant_id(),actor=a.actorId();
  String request=schema.canonical(Map.of("schema_version","1.0.0","invocation_id",invocation,"reason",reason));String requestHash=WireValues.sha256(request.getBytes(java.nio.charset.StandardCharsets.UTF_8));var old=db.query("SELECT request_sha256,receipt_json,receipt_sha256 FROM formal_invocation_cancellation WHERE tenant_id=? AND created_by=? AND idempotency_key=? LIMIT 2",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3)),tenant,actor,key);if(old.size()>1)bad();if(!old.isEmpty()){if(!old.get(0).get(0).equals(requestHash))throw new TenantAccessException(ErrorCode.IDEMPOTENCY_CONFLICT);return verify(job,key,request,old.get(0).get(1),old.get(0).get(2));}
  requireAbsentAudit(tenant,actor,key);
  var state=one(db.query("SELECT status,dispatch_generation,revision FROM invocation WHERE tenant_id=? AND invocation_id=? LIMIT 2 FOR UPDATE",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3)),tenant,invocation));var attempts=db.query("SELECT attempt_id FROM formal_invocation_attempt WHERE tenant_id=? AND invocation_id=? LIMIT 2",(r,n)->r.getString(1),tenant,invocation);if(attempts.size()>1)bad();boolean before="RESERVED".equals(state.get(0));if(before&&(!"0".equals(state.get(1))||!attempts.isEmpty())||!before&&("0".equals(state.get(1))||attempts.size()!=1))bad();
  if(before){var sent=one(db.queryForList("SELECT actual_send_manifest,actual_send_sha256,provider_request_id,usage_receipt_id FROM invocation WHERE tenant_id=? AND invocation_id=? LIMIT 2",tenant,invocation));for(String field:List.of("actual_send_manifest","actual_send_sha256","provider_request_id","usage_receipt_id"))if(sent.get(field)!=null)bad();}
  if(Set.of("SUCCEEDED","FAILED","CANCELLED").contains(state.get(0)))throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);
  var now=one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));
  if(before){var rows=db.query("SELECT reservation_id,budget_id,upper_amount,upper_tokens,revision,status FROM budget_reservation WHERE tenant_id=? AND invocation_id=? ORDER BY budget_id LIMIT 3 FOR UPDATE",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6)),tenant,invocation);if(rows.size()!=2)bad();for(var r:rows){if(!"RESERVED".equals(r.get(5)))bad();var account=one(db.query("SELECT revision,reserved,reserved_tokens,reserved_calls FROM budget_account WHERE tenant_id=? AND budget_id=? LIMIT 2 FOR UPDATE",(rs,n)->List.of(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4)),tenant,r.get(1)));if(new BigDecimal(account.get(1)).compareTo(new BigDecimal(r.get(2)))<0||new BigInteger(account.get(2)).compareTo(new BigInteger(r.get(3)))<0||new BigInteger(account.get(3)).signum()<=0)bad();changed(db.update("UPDATE budget_account SET reserved=reserved-?,reserved_tokens=reserved_tokens-?,reserved_calls=reserved_calls-1,revision=revision+1,updated_at=? WHERE tenant_id=? AND budget_id=? AND revision=?",r.get(2),r.get(3),now,tenant,r.get(1),account.get(0)));changed(db.update("UPDATE budget_reservation SET status='RELEASED',revision=revision+1,updated_at=? WHERE tenant_id=? AND reservation_id=? AND revision=? AND status='RESERVED'",now,tenant,r.get(0),r.get(4)));}}
  // If an immutable UNKNOWN observation exists, preserve its actual execution/accounting snapshot.
  boolean hasObservation=!db.query("SELECT invocation_id FROM formal_invocation_accounting WHERE tenant_id=? AND invocation_id=? LIMIT 2",(r,n)->r.getString(1),tenant,invocation).isEmpty();String next=before?"CANCELLED":hasObservation?state.get(0):"CANCEL_REQUESTED";
  changed(db.update("UPDATE invocation SET status=?,revision=revision+1,updated_at=? WHERE tenant_id=? AND invocation_id=? AND revision=?",next,now,tenant,invocation,state.get(2)));
  if(before&&!job.task()){changed(db.update("UPDATE run_step SET status='CANCELLED',revision=revision+1,updated_at=? WHERE tenant_id=? AND run_id=? AND step_id=? AND status IN ('READY','RUNNING')",now,tenant,job.run(),job.step()));changed(db.update("UPDATE system_job_run SET status='CANCELLED',ended_at=?,revision=revision+1,updated_at=? WHERE tenant_id=? AND run_id=? AND status='RUNNING'",now,now,tenant,job.run()));}
  var receipt=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("schema_version","1.0.0").put("invocation_id",invocation).put("verification_id",job.verification()).put("request_body_sha256",requestHash).put("original_key_sha256",keyHash(key)).put("status",next).put("before_dispatch",before).put("reservations_released",before).put("provider_termination_confirmed",false).put("created_at",now.toInstant(ZoneOffset.UTC).toString());String raw=schema.canonical(receipt),hash=schema.hash(receipt);var row=meta(job,now);row.put("invocation_id",invocation);row.put("idempotency_key",key);row.put("canonical_request",request);row.put("request_sha256",requestHash);row.put("receipt_json",raw);row.put("receipt_sha256",hash);insert("formal_invocation_cancellation",row);var audit=meta(job,now);audit.put("audit_id",UUID.randomUUID().toString());audit.put("subject_id",actor);audit.put("action","model.invocation_cancel_requested");audit.put("resource_ref",raw);audit.put("result","SUCCESS");audit.put("request_id",requestHash);audit.put("trace_id",invocation);insert("audit_event",audit);insert("outbox_event",Map.of("tenant_id",tenant,"event_id",UUID.randomUUID().toString(),"aggregate_id",invocation,"aggregate_revision",new BigInteger(state.get(2)).add(BigInteger.ONE),"event_type","model.invocation_cancel_requested","payload",raw,"occurred_at",now));return verify(job,key,request,raw,hash);
 }
 Optional<JsonNode> recover(EnterpriseAccess.Admission a,String key)throws Exception{
  if(key==null||!key.matches("[!-~]{16,128}"))throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);String tenant=a.context().tenant_id(),actor=a.actorId();
  var rows=db.query("SELECT canonical_request,receipt_json,receipt_sha256 FROM formal_invocation_cancellation WHERE tenant_id=? AND created_by=? AND idempotency_key=? LIMIT 2",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3)),tenant,actor,key);if(rows.size()>1)bad();if(rows.isEmpty()){requireAbsentAudit(tenant,actor,key);return Optional.empty();}
  var request=schema.parse(rows.get(0).get(0));String invocation=request.required("invocation_id").textValue();var run=one(db.query("SELECT run_id,created_by,config_id FROM invocation WHERE tenant_id=? AND invocation_id=? LIMIT 2",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3)),tenant,invocation));if(!actor.equals(run.get(1)))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);var job=jobs.byRun(tenant,run.get(0));reservations.requireRegistered(job,invocation);resources.require(a,new PermissionProtocol.Scope(tenant,job.project(),"CONFIGURATION",run.get(2)),"model.verify","MODEL_VERIFICATION");return Optional.of(verify(new FormalInvocationBinding.Verification(job),key,rows.get(0).get(0),rows.get(0).get(1),rows.get(0).get(2)));
 }
 private static void validate(String key,String reason){if(key==null||!key.matches("[!-~]{16,128}")||reason==null||reason.isBlank()||reason.length()>2000||!reason.equals(reason.strip()))throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);}
 private void requireAbsentAudit(String tenant,String actor,String key)throws Exception{var evidence=db.query("SELECT audit_id FROM audit_event WHERE tenant_id=? AND subject_id=? AND action='model.invocation_cancel_requested' AND JSON_UNQUOTE(JSON_EXTRACT(resource_ref,'$.original_key_sha256'))=? LIMIT 2",(r,n)->r.getString(1),tenant,actor,keyHash(key));if(!evidence.isEmpty())bad();}
 private static String keyHash(String key)throws Exception{return WireValues.sha256(key.getBytes(java.nio.charset.StandardCharsets.US_ASCII));}
 private JsonNode verify(FormalInvocationBinding job,String key,String request,String raw,String hash)throws Exception{var r=schema.parse(raw);if(!keyHash(key).equals(r.required("original_key_sha256").textValue())||!raw.equals(schema.canonical(r))||!hash.equals(schema.hash(r))||!WireValues.sha256(request.getBytes(java.nio.charset.StandardCharsets.UTF_8)).equals(r.required("request_body_sha256").textValue()))bad();var now=LocalDateTime.ofInstant(Instant.parse(r.required("created_at").textValue()),ZoneOffset.UTC);if(one(db.query("SELECT COUNT(*) FROM formal_invocation_cancellation WHERE tenant_id=? AND project_id=? AND invocation_id=? AND idempotency_key=? AND canonical_request=? AND request_sha256=? AND receipt_json=? AND receipt_sha256=? AND created_by=? AND created_at=? AND schema_version='1.0.0' AND schema_manifest_sha256=? AND classification=?",(rs,n)->rs.getInt(1),job.tenant(),job.project(),r.required("invocation_id").textValue(),key,request,r.required("request_body_sha256").textValue(),raw,hash,job.actor(),now,schema.manifestSha256(),job.classification()))!=1)bad();var audit=one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND subject_id=? AND action='model.invocation_cancel_requested' AND request_id=? AND trace_id=? AND created_at=? LIMIT 2",(rs,n)->rs.getString(1),job.tenant(),job.actor(),r.required("request_body_sha256").textValue(),r.required("invocation_id").textValue(),now));var event=one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND aggregate_id=? AND event_type='model.invocation_cancel_requested' AND occurred_at=? LIMIT 2",(rs,n)->rs.getString(1),job.tenant(),r.required("invocation_id").textValue(),now));if(!raw.equals(schema.canonical(schema.parse(audit)))||!raw.equals(schema.canonical(schema.parse(event))))bad();return r;}
 private Map<String,Object> meta(FormalInvocationBinding j,LocalDateTime now){var m=new LinkedHashMap<String,Object>();m.put("tenant_id",j.tenant());m.put("project_id",j.project());m.put("schema_version","1.0.0");m.put("schema_manifest_sha256",schema.manifestSha256());m.put("created_by",j.actor());m.put("created_at",now);m.put("classification",j.classification());return m;}private void insert(String table,Map<String,Object> v){var keys=new ArrayList<>(v.keySet());changed(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(v::get).toArray()));}private static void changed(int n){if(n!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);}private static <T>T one(List<T> r){if(r.size()!=1||r.get(0)==null)bad();return r.get(0);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
